using Microsoft.Win32;

namespace RemoteKeyboarGridBuilder
{
    internal static class Program
    {
        [STAThread]
        private static void Main()
        {
            // Generated by the WinForms SDK: sets high-DPI mode, default font and visual styles
            ApplicationConfiguration.Initialize();
            RegisterEditorPath();
            Application.Run(new MainForm());
        }

        private static void RegisterEditorPath()
        {
            try
            {
                using var key = Registry.CurrentUser.CreateSubKey(@"Software\RemoteKeyboard\Editor");
                key.SetValue("ExecutablePath", Application.ExecutablePath);
            }
            catch (Exception ex) when (ex is UnauthorizedAccessException or System.Security.SecurityException or System.IO.IOException)
            {
                System.Diagnostics.Debug.WriteLine($"Could not register the editor path: {ex.Message}");
            }
        }
    }
}
